'use strict';
const familyColors={절명:'#7051b7',연타:'#d97157',강타:'#a88c40',척살:'#5a8174',저격:'#438b43',주술:'#a32b3a',파멸:'#872e87',강인:'#23808c',기동:'#4a88b8',헌신:'#b7388c',기만:'#6673a0',제압:'#b17d36'};
const infoSymbols={target:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/><path d="M12 1v5m0 12v5M1 12h5m12 0h5"/>',cast:'<path d="M6 2h12M6 22h12M7 3v4l10 10v4M17 3v4L7 17v4M8 6h8M8 19h8"/>',cooldown:'<path d="M3 9a9 9 0 1 1 0 6M3 4v5h5M12 6v6l4 3"/>',range:'<path d="M8 3H3v5m0-5 7 7m6-7h5v5m0-5-7 7M3 16v5h5m-5 0 7-7m11 2v5h-5m5 0-7-7"/>'};
function statIcon(name){return `<svg class="stat-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${infoSymbols[name]}</svg>`;}
function basicStats(s,compact=false){const labels={target:'대상',cast:'시전 방식',cooldown:compact?'재사용':'재사용 대기시간',range:'사거리'};return `<dl class="${compact?'list-basic':'game-basic'}">${Object.keys(labels).map(key=>`<div title="${esc(s.basic?.fieldNotes?.[key]||s.basic?.note||'공식 자료에 수치 미기재')}">${compact?'':statIcon(key)}<div><dt>${labels[key]}</dt><dd>${esc(valueStat(s,key))}${s.basic?.referenceFields?.includes(key)?'<span class="inferred" title="비공식 도감 참고값입니다. 공식 확인값과 구분해 표시합니다.">※</span>':''}</dd></div></div>`).join('')}</dl>`;}
function renderList(){const q=$('#search').value.trim(),fam=$('#family').value,list=S.filter(s=>(!fam||s.family===fam)&&DosulTargets.matches(s,targetFilter)&&searchMatch(s,q));$('#list-count').textContent=list.length+'개';renderMarkup('#skill-list',list.map(s=>`<button class="skill-item ${selected===s.id?'selected':''}" data-select="${s.id}"><span class="list-heading">${icon(s)}<span><b class="skill-title">${esc(s.name)}</b>${skillTags(s)}<small>${s.category||'도술'}</small></span>${build.includes(s.id)?`<span class="in-build">${build.indexOf(s.id)+1}</span>`:''}</span>${basicStats(s,true)}</button>`).join('')||'<p class="empty">검색 결과가 없습니다.</p>');}
function rawEffectRows(s){if(s.gameDetail)return s.gameDetail;if(s.referenceDetail)return s.referenceDetail;const negative=new Set(['방어력 감소','받는 피해 증가','이동 속도 감소','받는 회복 감소','치유 효과 감소']);const out={buffs:s.buffs.map(name=>({name,description:name==='슈퍼 아머'?'모든 군중 제어 효과에 면역이 됩니다.':`자신에게 ${name} 효과 부여`})),debuffs:s.debuffs.map(name=>({name,description:`대상에게 ${name} 효과 부여`}))};for(const c of s.conditions){out[negative.has(c.result)?'debuffs':'buffs'].push({name:`${c.effect} (${c.result})`,description:`${c.scope==='self'?'자신':'대상'}의 ${c.effect} 조건 충족 시 ${c.result}`});}return out;}
function effectRows(s){const detail=rawEffectRows(s),map=items=>(items||[]).map(e=>{const d=DosulTiming.duration(s,e.name);return {...e,duration:d.value===null?e.duration:d.value+'초'};});return {...detail,buffs:map(detail.buffs),debuffs:map(detail.debuffs)};}
function effectSection(items,kind){return `<section class="game-effects ${kind}"><h3><span aria-hidden="true">❖</span>${kind==='buffs'?'강화 효과':'약화 효과'}<span aria-hidden="true">❖</span></h3>${items.length?items.map(e=>`<div class="game-effect"><span class="effect-icon" aria-hidden="true"><svg viewBox="0 0 32 32"><path d="${kind==='buffs'?'M16 3 5 16h7v12h8V16h7Z':'M16 29 5 16h7V4h8v12h7Z'}"/></svg></span><div><div class="effect-title"><b>${esc(e.name)}</b>${e.duration?`<span>${esc(e.duration)}</span>`:''}</div><p>${highlight(e.description,kind)}</p></div></div>`).join(''):'<p class="effect-empty">공개 자료에 기재된 효과 없음</p>'}</section>`;}
function highlight(text,kind='damage'){return esc(text).replace(/(\d+(?:\.\d+)?%|\d+회)/g,`<strong class="value-${kind}">$1</strong>`);}
function renderDetail(){if(!byId(selected))return renderEmptyDetail();const s=byId(selected),src=source(s),v=Q.validate(D,build),result=Q.place(D,build,step,s.id,insertMode?'insert':'replace'),connections=Q.links(D,E,build,step,s.id).filter(e=>types().includes(e.type)),count=v.counts[s.family]||0,detail=effectRows(s),basis=D.sources.find(x=>x.id===s.basic?.source),captured=s.gameDetail;
 renderMarkup('#detail',`<p class="detail-eyebrow">도술 정보</p><div class="game-heading"><div class="game-skill-icon">${icon(s,'detail-icon')}${captured?`<span>${captured.levelLabel}</span>`:''}</div><div class="game-title"><h2>${esc(s.name)}</h2><div class="game-tags">${styleBadge(s)}${targetBadge(s)}<span class="game-category">${s.category||'일반'}</span>${captured?'<span class="game-mode">◉ PVE</span>':''}</div></div></div><div class="game-tabs"><span class="active">정보</span><span class="unavailable" title="각성·증강별 효과는 확인된 자료가 없어 표시하지 않습니다.">증강 <small>미확인</small></span></div><p class="game-description">${highlight(captured?.description||s.notes)}</p>${captured?'<p class="capture-note">첨부 화면의 +14 PVE 수치</p>':'<p class="capture-note">효과 수치: 깨비지지 참고 · 강화 단계에 따라 달라질 수 있습니다.</p>'}${basicStats(s)}${typeof mechanicFacts==='function'?mechanicFacts(s):''}${effectSection(detail.buffs,'buffs')}${effectSection(detail.debuffs,'debuffs')}${(s.specialRules||[]).map(r=>`<p class="capture-note"><b>${esc(r.name)}</b> ${esc(r.description)}</p>`).join('')}${referenceStats(s)}<div class="game-actions">${s.ultimate?`<p class="ult-rule ${count>=3?'good':'warn'}">${s.family} 일반 도술 ${count}/3 · ${count>=3?'궁극기 조건 충족':'조건 미충족 · 계획 배치 가능'}</p>`:''}<button class="primary" id="add" ${result.error?'disabled':''}>${result.error?esc(result.error):`${step+1}단계에 ${insertMode?'끼워넣기':build[step]?'교체':'배치'} →`}</button></div><details class="game-extra"><summary>연계 근거 · ${connections.length}개</summary>${connections.length?connections.map(e=>`<p class="${e.type==='conflict'?'warn':''}">${esc(reason(e))}${e.missing.length?'<br><small>필요: '+esc(e.missing.join(', '))+'</small>':''}</p>`).join(''):'<p>앞 단계에서 확인된 연계가 없습니다.</p>'}</details><details class="game-extra"><summary>${s.family} 신식</summary><p>${esc(D.families[s.family])}</p>${(D.familyReference?.[s.family]||[]).map(x=>`<p><b>${esc(x.s)}</b> ${esc(x.d)}</p>`).join('')}<small>상세: 깨비지지 교차 대조 참고</small></details><p class="bug-status">${s.family==='주술'?'🐞 타 계열 쿨타임 감소 버그 있음 · 연결 유지':'버그 유무 미확인'}</p><details class="game-extra provenance"><summary>정보 출처${s.basic?.referenceFields?.length?' · ※ 비공식 참고값':''}</summary><p>${esc(DosulTargets.get(s).note)}</p>${D.sources.find(x=>x.id===DosulTargets.get(s).source)?.url?`<p><a href="${esc(D.sources.find(x=>x.id===DosulTargets.get(s).source)?.url||source(s).url)}" target="_blank" rel="noopener noreferrer">대상 종류 근거 ↗</a></p>`:''}<p>${esc(s.basic?.note)}</p>${(s.crosscheck?.conflicts||[]).map(c=>`<p class="source-conflict">재사용 대기시간: 기존 화면 ${c.observed}초 / 깨비지지 참고 ${Math.round(c.reference*100)/100}초. 강화·돌파 기준 차이를 확인하지 못해 기존 확인값을 유지합니다.</p>`).join('')}${s.effectAudit?`<p>${esc(s.effectAudit.note)}</p>`:''}${D.sources.find(x=>x.id===s.basic?.targetSource)?.url?`<p><a href="${esc(D.sources.find(x=>x.id===s.basic.targetSource)?.url)}" target="_blank" rel="noopener noreferrer">대상 정보 근거 ↗</a></p>`:''}${basis?.url?`<a href="${esc(basis.url)}" target="_blank" rel="noopener noreferrer">${esc(basis.title)} ↗</a>`:esc(basis?.title||'미확인')}<p><a href="${esc(src.url)}" target="_blank" rel="noopener noreferrer">공식 효과 설명 ↗</a></p></details>`);
 $('#add').onclick=()=>pick(s.id);
}
function renderTable(){const q=$('#table-search').value.trim(),list=S.filter(s=>searchMatch(s,q));$('#table-count').textContent=`${list.length} / 105개 · ※ 비공식 참고값 · 대상 종류와 인원 별도 표시 · ※ 비공식 참고 분류 포함`;$('#table-body').innerHTML=list.map(s=>`<tr><td><div class="table-skill">${icon(s)}<button data-table-select="${s.id}">${esc(s.name)} ↗</button>${skillTags(s)}</div><small>${s.family} / ${s.category}</small>${basicStats(s,true)}</td><td>${chips(s.buffs)}</td><td>${chips(s.debuffs,'debuff')}</td><td>${s.conditions.map(c=>esc(c.effect)+' → '+esc(c.result)).join('<br>')||'—'}</td><td>${esc(s.notes)}<br><a href="${esc(source(s).url)}" target="_blank" rel="noopener noreferrer">공식 출처 ↗</a></td></tr>`).join('');}
$('#download-csv').onclick=()=>{const cell=s=>'"'+String(s??'').replaceAll('"','""')+'"',rows=[['ID','도술','계열','구분','대상','시전 방식','재사용 대기시간(초)','사거리(m)','기본 정보 근거','강화','약화','조건','기능','버그 상태'],...S.map(s=>[s.id,s.name,s.family,s.category,valueStat(s,'target'),s.basic.cast,s.basic.cooldown,s.basic.range,s.basic.note,s.buffs.join(', '),s.debuffs.join(', '),s.conditions.map(c=>c.effect+' → '+c.result).join('; '),s.notes,s.family==='주술'?'타 계열 쿨타임 감소 버그 있음 (연결 유지)':'유무 미확인'])];download('도술-105개-목록.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');};

function referenceStats(s){const n=s.referenceNumbers;if(!n)return '';return `<details class="game-extra"><summary>공격 수치 · 비공식 참고</summary><p>깨비지지 기본 자료 · 강화·돌파·각성 미적용 기준입니다. 첨부 인게임 수치와 구분합니다.</p>${n.dc?.length?`<p>${n.dc.map(x=>`${Math.round(x.basic_coefficient*100)/100}% × ${x.hits}회`).join(' + ')}</p>`:'<p>공격계수 미기재</p>'}${s.crosscheck?.conflicts?.length?'<p>재사용 대기시간 출처 차이는 정보 출처에서 확인하세요.</p>':''}<a href="https://kkaebigg.com/skills/" target="_blank" rel="noopener noreferrer">레벨·돌파별 수치 비교 ↗</a></details>`;}

// Resolve the current renderer when filtering, rather than retaining the old renderer.
$('#search').oninput=()=>renderList();
$('#family').onchange=()=>renderList();
$('#table-search').oninput=()=>renderTable();
render();
